Use a sliding window with character deficits, preserving repeated-character requirements. Expand until all required characters are covered, then shrink while recording the shortest valid window.

```javascript
function solve(s, t) {
  if (t.length === 0 || s.length < t.length) return '';

  const need = new Map();
  for (let i = 0; i < t.length; i++) {
    const ch = t[i];
    need.set(ch, (need.get(ch) || 0) + 1);
  }

  let missing = t.length;
  let left = 0;
  let bestStart = 0;
  let bestLength = Infinity;

  for (let right = 0; right < s.length; right++) {
    const ch = s[right];
    if (need.has(ch)) {
      const count = need.get(ch);
      if (count > 0) missing--;
      need.set(ch, count - 1);
    }

    while (missing === 0) {
      const length = right - left + 1;
      if (length < bestLength) {
        bestLength = length;
        bestStart = left;
      }

      const outgoing = s[left++];
      if (need.has(outgoing)) {
        const count = need.get(outgoing) + 1;
        need.set(outgoing, count);
        if (count > 0) missing++;
      }
    }
  }

  return bestLength === Infinity
    ? ''
    : s.slice(bestStart, bestStart + bestLength);
}
```

Call solve(s, t) directly; no imports, exports, or stdin/stdout are needed. Time: O(s.length + t.length). Auxiliary space: O(k), where k is the number of distinct characters in t, excluding the returned substring.

