Build consecutive-one column heights for each row, then use a monotonic stack to find its largest histogram rectangle. Time: O(rows × columns); extra space: O(columns). Call solve(matrix) directly; the input is not modified.

```javascript
function solve(matrix) {
  if (matrix.length === 0 || matrix[0].length === 0) return 0;

  const columns = matrix[0].length;
  const heights = new Array(columns).fill(0);
  let best = 0;

  for (const row of matrix) {
    for (let c = 0; c < columns; c++) {
      heights[c] = row[c] === '1' ? heights[c] + 1 : 0;
    }

    const stack = [];
    for (let c = 0; c <= columns; c++) {
      const current = c === columns ? 0 : heights[c];

      while (
        stack.length > 0 &&
        heights[stack[stack.length - 1]] > current
      ) {
        const height = heights[stack.pop()];
        const left = stack.length > 0
          ? stack[stack.length - 1]
          : -1;
        best = Math.max(best, height * (c - left - 1));
      }

      if (c < columns) stack.push(c);
    }
  }

  return best;
}
```

