Use prefix-count dynamic programming, updating backward so each source position is used at most once. Counts are capped at the guaranteed signed 32-bit maximum; this prevents large intermediate counts from losing precision without changing any valid final result.

```javascript
function solve(s, t) {
  if (t.length > s.length) return 0;

  const limit = 2147483647;
  const dp = new Array(t.length + 1).fill(0);
  dp[0] = 1;

  for (let i = 0; i < s.length; i++) {
    for (let j = Math.min(t.length, i + 1); j >= 1; j--) {
      if (s[i] === t[j - 1]) {
        dp[j] = Math.min(limit, dp[j] + dp[j - 1]);
      }
    }
  }

  return dp[t.length];
}
```

