Count each unvisited land cell as a new island, then mark its entire orthogonally connected component using iterative DFS. This preserves the input and returns 0 for empty grids. Call solve(grid) directly; time and auxiliary space are O(rows × cols).

```javascript
function solve(grid) {
  const rows = grid.length;
  if (rows === 0) return 0;
  const cols = grid[0].length;
  if (cols === 0) return 0;

  const visited = Array.from({ length: rows }, () =>
    new Uint8Array(cols)
  );
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let islands = 0;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] !== "1" || visited[r][c]) continue;

      islands++;
      visited[r][c] = 1;
      const stack = [[r, c]];

      while (stack.length > 0) {
        const [row, col] = stack.pop();
        for (const [dr, dc] of directions) {
          const nr = row + dr;
          const nc = col + dc;
          if (
            nr >= 0 && nr < rows &&
            nc >= 0 && nc < cols &&
            grid[nr][nc] === "1" && !visited[nr][nc]
          ) {
            visited[nr][nc] = 1;
            stack.push([nr, nc]);
          }
        }
      }
    }
  }

  return islands;
}
```

