Use a Set to ignore duplicates, and count a run only from a value whose predecessor is absent. Empty input returns 0; the input is unchanged. Expected time: O(n), assuming constant-time Set operations; space: O(n).

```javascript
function solve(nums) {
  const values = new Set(nums);
  let longest = 0;

  for (const value of values) {
    if (values.has(value - 1)) {
      continue;
    }

    let current = value;
    let length = 1;

    while (values.has(current + 1)) {
      current++;
      length++;
    }

    longest = Math.max(longest, length);
  }

  return longest;
}
```

