Track prefix-sum frequencies. Count earlier prefixes equal to the current sum minus k before recording the current prefix, so only nonempty subarrays are counted; negative values work too.

```javascript
function solve(nums, k) {
  const frequencies = new Map([[0, 1]]);
  let prefixSum = 0;
  let count = 0;

  for (const value of nums) {
    prefixSum += value;
    count += frequencies.get(prefixSum - k) ?? 0;
    frequencies.set(
      prefixSum,
      (frequencies.get(prefixSum) ?? 0) + 1
    );
  }

  return count;
}
```

