Add bits right to left with a carry, then remove leading zeros while preserving "0". No whole-value numeric conversion is used.

```javascript
function solve(a, b) {
  let i = a.length - 1;
  let j = b.length - 1;
  let carry = 0;
  const digits = [];

  while (i >= 0 || j >= 0 || carry !== 0) {
    let sum = carry;
    if (i >= 0) sum += a.charCodeAt(i--) - 48;
    if (j >= 0) sum += b.charCodeAt(j--) - 48;

    digits.push(String(sum % 2));
    carry = Math.floor(sum / 2);
  }

  while (digits.length > 1 && digits[digits.length - 1] === '0') {
    digits.pop();
  }

  return digits.reverse().join('');
}
```

