- `"()())()"`: the strongest lexicographic check. Exactly one closing must be removed; valid results include `"(())()"` and `"()()()"`. The implementation compares complete candidates and returns `"(())()"`, the smaller one.

The invariant is that the constructed prefix has nonnegative balance, preserves all encountered non-parenthesis characters, and uses exactly the tracked removal budgets. Accepting only zero balance and exhausted budgets guarantees validity and minimum removals; exploring every permitted choice guarantees the lexicographic minimum.

```javascript
function solve(s) {
  let removeOpen = 0;
  let removeClose = 0;

  for (const ch of s) {
    if (ch === '(') {
      removeOpen++;
    } else if (ch === ')') {
      if (removeOpen > 0) removeOpen--;
      else removeClose++;
    }
  }

  let best = null;
  const path = [];

  function search(i, balance, openLeft, closeLeft) {
    if (s.length - i < openLeft + closeLeft) return;

    if (i === s.length) {
      if (balance === 0 && openLeft === 0 && closeLeft === 0) {
        const candidate = path.join('');
        if (best === null || candidate < best) best = candidate;
      }
      return;
    }

    const ch = s[i];
    if (ch === '(') {
      if (openLeft > 0) {
        search(i + 1, balance, openLeft - 1, closeLeft);
      }
      path.push(ch);
      search(i + 1, balance + 1, openLeft, closeLeft);
      path.pop();
    } else if (ch === ')') {
      if (closeLeft > 0) {
        search(i + 1, balance, openLeft, closeLeft - 1);
      }
      if (balance > 0) {
        path.push(ch);
        search(i + 1, balance - 1, openLeft, closeLeft);
        path.pop();
      }
    } else {
      path.push(ch);
      search(i + 1, balance, openLeft, closeLeft);
      path.pop();
    }
  }

  search(0, 0, removeOpen, removeClose);
  return best;
}
```

