The screen asks for Levenshtein edit distance: the minimum number of insertions, deletions, and replacements to turn string a into b. Use dynamic programming over prefixes, choosing the cheapest of those three operations; matching characters cost nothing. This implementation takes O(a.length × b.length) time and O(min(a.length, b.length)) extra space, including empty-string cases.

```javascript
function solve(a, b) {
  if (a.length < b.length) [a, b] = [b, a];
  const m = a.length;
  const n = b.length;
  const dp = Array.from({ length: n + 1 }, (_, j) => j);

  for (let i = 1; i <= m; i++) {
    let diagonal = dp[0];
    dp[0] = i;
    for (let j = 1; j <= n; j++) {
      const above = dp[j];
      dp[j] = Math.min(
        above + 1,                         // Delete from a
        dp[j - 1] + 1,                     // Insert into a
        diagonal + (a[i - 1] === b[j - 1] ? 0 : 1)
      );
      diagonal = above;
    }
  }
  return dp[n];
}
