function solve(a, b) {
  if (a.length < b.length) [a, b] = [b, a];
  const m = a.length;
  const n = b.length;
  if (n === 0) return m;

  const dp = Array.from({ length: n + 1 }, (_, j) => j);

  for (let i = 1; i <= m; i++) {
    let diagonal = dp[0];
    dp[0] = i;

    for (let j = 1; j <= n; j++) {
      const above = dp[j];
      dp[j] = Math.min(
        above + 1,
        dp[j - 1] + 1,
        diagonal + (a[i - 1] === b[j - 1] ? 0 : 1)
      );
      diagonal = above;
    }
  }

  return dp[n];
}
```

