```javascript
function solve(nums) {
  const sorted = nums.slice().sort((a, b) => a - b);
  const used = new Array(sorted.length).fill(false);
  const path = [];
  const result = [];

  function search() {
    if (path.length === sorted.length) {
      result.push(path.slice());
      return;
    }

    for (let i = 0; i < sorted.length; i++) {
      if (used[i]) continue;
      if (i > 0 && sorted[i] === sorted[i - 1] && !used[i - 1]) {
        continue;
      }

      used[i] = true;
      path.push(sorted[i]);
      search();
      path.pop();
      used[i] = false;
    }
  }

  search();
  return result;
}
```

