export function solve(n, edges, source) {
  const d = Array(n).fill(Infinity);
  const q = [[0, source]];
  d[source] = 0;

  while (q.length) {
    q.sort((a, b) => a[0] - b[0]);
    const [c, u] = q.shift();
    if (c !== d[u]) continue;

    for (const [a, b, w] of edges) {
      if (a !== u) continue;
      const candidate = c + w;
      if (candidate < d[b]) {
        d[b] = candidate;
        q.push([candidate, b]);
      }
    }
  }

  return d.map(x => Number.isFinite(x) ? x : null);
}

