Use a min-heap holding one value from each nonempty list, tracking their maximum. Repeatedly evaluate the range and advance the list supplying the minimum; stop when that list is exhausted. The attachment does not specify the all-empty case; this implementation returns [] when no nonempty lists exist.

```javascript
function solve(lists) {
  const heap = [];
  let maximum = -Infinity;

  function siftDown(index) {
    while (true) {
      const left = index * 2 + 1;
      const right = left + 1;
      let smallest = index;

      if (left < heap.length &&
          heap[left].value < heap[smallest].value) {
        smallest = left;
      }
      if (right < heap.length &&
          heap[right].value < heap[smallest].value) {
        smallest = right;
      }
      if (smallest === index) return;

      [heap[index], heap[smallest]] =
        [heap[smallest], heap[index]];
      index = smallest;
    }
  }

  for (const list of lists) {
    if (list.length === 0) continue;
    heap.push({ value: list[0], list, index: 0 });
    maximum = Math.max(maximum, list[0]);
  }

  if (heap.length === 0) return [];

  for (let i = Math.floor(heap.length / 2) - 1; i >= 0; i--) {
    siftDown(i);
  }

  let bestLeft = heap[0].value;
  let bestRight = maximum;

  while (true) {
    const minimum = heap[0];
    const left = minimum.value;
    const width = maximum - left;
    const bestWidth = bestRight - bestLeft;

    if (width < bestWidth ||
        (width === bestWidth && left < bestLeft)) {
      bestLeft = left;
      bestRight = maximum;
    }

    const nextIndex = minimum.index + 1;
    if (nextIndex === minimum.list.length) break;

    minimum.index = nextIndex;
    minimum.value = minimum.list[nextIndex];
    maximum = Math.max(maximum, minimum.value);
    siftDown(0);
  }

  return [bestLeft, bestRight];
}
```

