Scan once: copy intervals before the insertion, merge overlaps including touching endpoints, then copy the rest. Inputs are not modified. Time: O(n); output space: O(n), with O(1) auxiliary space excluding the output.

```javascript
function solve(intervals, interval) {
  const result = [];
  let [start, end] = interval;
  let i = 0;

  while (i < intervals.length && intervals[i][1] < start) {
    result.push([...intervals[i]]);
    i++;
  }

  while (i < intervals.length && intervals[i][0] <= end) {
    start = Math.min(start, intervals[i][0]);
    end = Math.max(end, intervals[i][1]);
    i++;
  }

  result.push([start, end]);

  while (i < intervals.length) {
    result.push([...intervals[i]]);
    i++;
  }

  return result;
}
```

