Use a circular buffer to preserve FIFO order and reject pushes when full. Capacity zero rejects every push and returns null for every pop.

```javascript
function solve(capacity, operations) {
  const buffer = [];
  const results = [];
  let head = 0;
  let size = 0;

  for (const [operation, value] of operations) {
    if (operation === "push") {
      if (size === capacity) {
        results.push(false);
      } else {
        buffer[(head + size) % capacity] = value;
        size++;
        results.push(true);
      }
    } else if (operation === "pop") {
      if (size === 0) {
        results.push(null);
      } else {
        const next = buffer[head];
        buffer[head] = undefined;
        head = (head + 1) % capacity;
        size--;
        results.push(next);
      }
    }
  }

  return results;
}
```

Call `solve(capacity, operations)` directly. For n operations, time is O(n); queue storage is O(min(capacity, n)), plus O(n) for the returned results.

